export function Kpi({
  label = "{{label}}",
  value = "{{value}}",
  change = "{{change}}",
  trend = "{{trend}}",
  target = "{{target}}",
  accent = "{{accent}}",
}) {
  const trendStyle = {
    up: { background: "#A8E6C133", color: "#1c6b3f", icon: "▲" },
    down: { background: "#F5C2E055", color: "#8a1f56", icon: "▼" },
    flat: { background: "#24143014", color: "#241430", icon: "▬" },
  }[trend] ?? { background: "#24143014", color: "#241430", icon: "▬" };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 16, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", borderRadius: 14, padding: "22px 24px", boxShadow: "0 8px 24px rgba(36,20,48,.12)",
      maxWidth: 280, boxSizing: "border-box", borderTop: `4px solid ${accent}` }}>
      <p style={{ margin: "0 0 6px", fontSize: 13, fontWeight: 600, textTransform: "uppercase",
        letterSpacing: ".04em", color: "#24143099" }}>{label}</p>
      <p style={{ margin: "0 0 10px", fontSize: 34, fontWeight: 700 }}>{value}</p>
      <div style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px",
        borderRadius: 999, fontSize: 13, fontWeight: 600, marginBottom: 14,
        background: trendStyle.background, color: trendStyle.color }}>
        <span aria-hidden="true">{trendStyle.icon}</span>
        <span>{change}</span>
      </div>
      <dl style={{ margin: 0, display: "flex", gap: 6, fontSize: 13, color: "#241430aa" }}>
        <dt style={{ fontWeight: 600 }}>Target:</dt>
        <dd style={{ margin: 0 }}>{target}</dd>
      </dl>
    </div>
  );
}
